  "sim.progress.welcomeBack": "🔄 Chào mừng trở lại! Tiến độ của bạn đã được khôi phục — Điểm: {score}",
  "sim.progress.alreadyCompleted": "🔄 Chào mừng trở lại! Bạn đã hoàn thành mô phỏng này rồi.",
  "sim.egg-incubator.title": "Trại ấp trứng",
  "sim.egg-incubator.desc": "Quản lý nhiệt độ, độ ẩm và việc xoay trứng trong trại ấp để tối đa hóa tỷ lệ nở.",
  "sim.dairy-farm.title": "Trang trại bò sữa",
  "sim.dairy-farm.desc": "Vận hành một trang trại bò sữa quy mô nhỏ: lịch cho ăn, chu kỳ vắt sữa và sức khỏe đàn để tối đa hóa sản lượng.",
  "sim.poultry-farm.title": "Trang trại gia cầm",
  "sim.poultry-farm.desc": "Quản lý một trang trại gia cầm thương mại — thức ăn, sức khỏe và chỉ tiêu sản xuất cho đàn gà thịt và gà đẻ.",
  "sim.cattle-dairy.title": "Bò & Bò sữa",
  "sim.cattle-dairy.desc": "Theo dõi một trang trại chăn nuôi bò và đơn vị bò sữa, cân bằng quản lý đồng cỏ, chăn giống và sản xuất sữa.",
  "sim.sheep-farm.title": "Trang trại cừu",
  "sim.sheep-farm.desc": "Vận hành trang trại cừu theo các chu kỳ theo mùa: cừu con ra đời, cắt lông và bán hàng trên thị trường.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Hãy đóng vai kỹ sư Trung tâm Vận hành Mạng (NOC) — chẩn đoán và xử lý sự cố hạ tầng trực tiếp trong điều kiện áp lực cao.",
  "sim.mobile-repair.title": "Xưởng Sửa Chữa Điện Thoại Di Động",
  "sim.mobile-repair.desc": "Chẩn đoán và sửa điện thoại — thay màn hình, xử lý lỗi pin và lỗi bo mạch chủ.",
  "sim.laptop-repair.title": "Xưởng Sửa Chữa Laptop",
  "sim.laptop-repair.desc": "Khắc phục và sửa laptop: lỗi phần cứng, sự cố BIOS và thay thế linh kiện.",
  "sim.perfume-lab.title": "Phòng thí nghiệm Nước hoa",
  "sim.perfume-lab.desc": "Trộn tinh dầu và các hợp chất tạo mùi để tạo hương đặc trưng, đồng thời đạt chuẩn chất lượng.",
  "sim.detergent-lab.title": "Phòng Thí Nghiệm Chất Tẩy Rửa",
  "sim.detergent-lab.desc": "Pha chế sản phẩm làm sạch — cân bằng chất hoạt động bề mặt, chất độn và các bài kiểm tra hiệu năng trong ngân sách.",
  "sim.skin-care-lab.title": "Phòng Thí Nghiệm Chăm Sóc Da",
  "sim.skin-care-lab.desc": "Phát triển và kiểm thử công thức mỹ phẩm, đáp ứng tiêu chuẩn an toàn và mục tiêu hiệu quả.",
  "sim.woodworking.title": "Xưởng Mộc",
  "sim.woodworking.desc": "Vận hành xưởng mộc theo yêu cầu: lên kế hoạch công việc, quản lý vật liệu và giao đồ nội thất đúng tiến độ, đúng ngân sách.",
  "sim.aluminum-glazing.title": "Nhôm & Kính",
  "sim.aluminum-glazing.desc": "Quản lý hoạt động gia công nhôm và lắp đặt kính từ lúc báo giá đến khi hoàn tất công trình.",
  "sim.global-kitchen.title": "Bếp Toàn Cầu",
  "sim.global-kitchen.desc": "Điều hành bếp nhà hàng: quản lý thực đơn, nhân sự, chi phí và mức độ hài lòng của khách hàng trong các ca phục vụ.",
  "sim.chocolate-factory.title": "Nhà Máy Sản Xuất Socola",
  "sim.chocolate-factory.desc": "Vận hành nhà máy bánh kẹo — thu mua cacao, lên lịch sản xuất và kiểm soát chất lượng.",
  "sim.solar-energy.title": "Nhà Máy Điện Năng Lượng Mặt Trời",
  "sim.solar-energy.desc": "Thiết kế và vận hành lắp đặt điện mặt trời — tính kích thước tấm pin, quản lý xuất điện lên lưới và theo dõi ROI.",
  "sim.hvac-systems.title": "Hệ Thống HVAC",
  "sim.hvac-systems.desc": "Lắp đặt và bảo trì hệ thống sưởi, thông gió và điều hòa không khí cho công trình thương mại.",
  "sim.logistics-supply.title": "Logistics & Chuỗi Cung Ứng",
  "sim.logistics-supply.desc": "Tối ưu hóa vận hành kho, tuyến đường xe và mối quan hệ với nhà cung cấp để đạt KPI giao hàng.",
  "sim.barber-salon.title": "Tiệm Tóc Nam",
  "sim.barber-salon.desc": "Quản lý tiệm cắt tóc: đặt lịch, sắp xếp nhân sự, định giá và chiến lược giữ chân khách hàng.",
  "sim.board-surgeon.title": "Bác Sĩ Phẫu Thuật",
  "sim.board-surgeon.desc": "Đưa ra quyết định phẫu thuật trong tình huống cấp bách tại phòng mổ mô phỏng — quản lý thời gian và đảm bảo an toàn cho bệnh nhân.",
  "sim.english-journey.title": "Hành Trình Tiếng Anh",
  "sim.english-journey.desc": "Dẫn dắt người học qua chương trình tiếng Anh có cấu trúc, điều chỉnh theo các mức độ năng lực khác nhau.",
  "sim.music-training.title": "Studio Đào Tạo Âm Nhạc",
  "sim.music-training.desc": "Vận hành trường âm nhạc: lên lịch học, quản lý nhạc cụ và theo dõi tiến độ học viên hướng tới buổi biểu diễn.",
  "sim.trade-tycoon.title": "Kẻ Thống Trị Thương Mại",
  "sim.trade-tycoon.desc": "Xây dựng đế chế giao dịch — mua thấp, bán cao, quản lý hàng tồn kho và dòng tiền qua nhiều thị trường.",
  "sim.vehicle-diagnostics.title": "Trình mô phỏng chẩn đoán & sửa chữa xe",
  "sim.vehicle-diagnostics.desc": "Chẩn đoán mã lỗi OBD-II, truy vết lỗi điện và quản lý quy trình sửa chữa ô tô trong thế giới thực.",
  "sim.marine-vessel.title": "Theo Dõi Tàu Vận & Logistics Hàng Hải",
  "sim.marine-vessel.desc": "Chỉ huy đội tàu toàn cầu — theo dõi tàu, điều hướng ùn tắc cảng, xử lý khẩn cấp thời tiết và chờ trễ kênh đào.",
  "sim.brief.budget": "Ngân sách",
